sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float feather;
layout(color) uniform half4 color1;
uniform float threshold1;
layout(color) uniform half4 color2;
uniform float threshold2;
layout(color) uniform half4 color3;
uniform float threshold3;
float edgeDistance(float2 coord) {
    float b = clamp(float(blurred.eval(coord).a), 0.0005, 0.9995);
    return blur / 3.0 * log(b / (1.0 - b)) / 1.702;
}
float keep(float3 rgb, half4 k, float range) {
    if (range <= 0.0) return 0.0;
    return 1.0 - smoothstep(range * (1.0 - feather), range + 0.0001, distance(rgb, float3(k.rgb)));
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0 || blur <= 0.0) return c;
    float w = 1.0 - smoothstep(blur * (1.0 - feather), blur + 0.0001, edgeDistance(coord));
    float3 rgb = float3(unpremul(c).rgb);
    w *= 1.0 - max(keep(rgb, color1, threshold1), max(keep(rgb, color2, threshold2), keep(rgb, color3, threshold3)));
    float3 grey = float3(dot(rgb, float3(0.299, 0.587, 0.114))) + float3(-0.027, 0.004, 0.035);
    return half4(half3(clamp(mix(rgb, grey, w), 0.0, 1.0)) * c.a, c.a);
}
